import XCTest

extension RunnerTests {
#if AGENT_DEVICE_RUNNER_UNIT_TESTS && os(iOS)
  @MainActor
  func testConfirmedInputReadinessReturnsBeforeItsReadinessWindow() throws {
    app.launchArguments = ["--agent-device-text-entry-regression"]
    app.launch()
    defer { invalidateCachedTarget(reason: "unit_test_cleanup"); app.terminate() }
    XCTAssertTrue(app.waitForExistence(timeout: appExistenceTimeout))
    let field = app.textFields["agent-device-hardware-keyboard-input"]
    XCTAssertTrue(field.waitForExistence(timeout: appExistenceTimeout))
    field.tap()
    XCTAssertTrue(keyboardFocusConfirmed(app: app, element: field))
    let failures = currentXCTestFailureCount()
    let startedAt = Date()
    waitForTextEntryReadinessAfterTap(app: app, element: field)
    let elapsed = Date().timeIntervalSince(startedAt)
    NSLog("OTHER_PATHS_READINESS durationMs=%.3f", elapsed * 1000)
    XCTAssertFalse(didRecordXCTestFailure(since: failures))
    XCTAssertTrue(keyboardFocusConfirmed(app: app, element: field))
    XCTAssertLessThan(elapsed, TextEntryTiming.readinessTimeout)
  }

  @MainActor
  func testProfileUpstreamForm() throws {
    let benchmark = XCUIApplication(bundleIdentifier: "dev.e2e.benchmark")
    benchmark.launch()
    defer { invalidateCachedTarget(reason: "unit_test_cleanup"); benchmark.terminate() }
    XCTAssertTrue(benchmark.waitForExistence(timeout: appExistenceTimeout))
    let row = benchmark.descendants(matching: .any).matching(identifier: "Login Form").firstMatch
    guard row.waitForExistence(timeout: appExistenceTimeout) else {
      XCTFail("home row missing: \(benchmark.debugDescription)")
      return
    }
    row.tap()
    let field = benchmark.textFields["email-input"]
    XCTAssertTrue(field.waitForExistence(timeout: appExistenceTimeout))
    mainOwned.app = benchmark
    mainOwned.bundleId = "dev.e2e.benchmark"
    mainOwned.processIdentifier = try XCTUnwrap(Self.processIdentifier(of: benchmark))
    clearSnapshotXCTestChannelPenalty(reason: "profile-baseline")
    func fill(_ text: String, kind: String, round: Int) throws {
      let frame = field.frame
      let command = try JSONDecoder().decode(Command.self, from: JSONSerialization.data(withJSONObject: [
        "command": "type", "commandId": "profile-\(kind)-\(round)", "text": text,
        "textEntryMode": "replace", "x": frame.midX, "y": frame.midY,
      ]))
      let startedAt = Date()
      let response = try executeOnMainPrepared(command: command, activeApp: benchmark)
      let elapsed = Date().timeIntervalSince(startedAt) * 1000
      XCTAssertTrue(response.ok, String(describing: response.error))
      XCTAssertEqual(field.value as? String, text.isEmpty ? "Email" : text)
      NSLog("OTHER_PATHS_BENCH kind=%@ round=%d durationMs=%.3f", kind, round, elapsed)
    }
    for round in 0..<4 {
      try fill("", kind: "clear", round: round)
      try fill("user00@example.test", kind: "fill-empty", round: round)
      try fill("next00@example.test", kind: "fill-replace", round: round)
      let tap = try runnerCommandFixture(
        #"{"command":"tap","commandId":"profile-selector-input","selectorKey":"id","selectorValue":"email-input","synthesized":true}"#
      )
      let startedAt = Date()
      let tapped = try executeOnMainPrepared(command: tap, activeApp: benchmark)
      let elapsed = Date().timeIntervalSince(startedAt) * 1000
      XCTAssertTrue(tapped.ok, String(describing: tapped.error))
      XCTAssertTrue(keyboardFocusConfirmed(app: benchmark, element: field))
      XCTAssertEqual(field.value as? String, "next00@example.test")
      NSLog("OTHER_PATHS_BENCH kind=selector-input round=%d durationMs=%.3f", round, elapsed)
    }
  }
#endif
}

