import fs from 'node:fs';
import assert from 'node:assert/strict';
import {pathToFileURL} from 'node:url';
const [root,repo,label]=process.argv.slice(2);
const {PNG}=await import(pathToFileURL(`${root}/packages/capture-kit/src/png.ts`));
const {resizePngBox:reference}=await import(pathToFileURL(`${root}/packages/capture-kit/src/png-resize.ts`));
const {resizePngBox:resize}=await import(pathToFileURL(`${repo}/packages/capture-kit/src/png-resize.ts`));
const source=PNG.sync.read(fs.readFileSync('/private/tmp/e2e-ios-bench/direct/screenshots/001-bench-0.png'));
const results=[];
for(const [width,height] of [[402,874],[603,1311],[481,1047]]){
 const expected=reference(source,width,height),samples=[];
 for(let i=0;i<22;i++){
  const start=performance.now();const actual=resize(source,width,height);const ms=performance.now()-start;
  assert.deepEqual(actual.data,expected.data);assert.equal(actual.width,width);assert.equal(actual.height,height);
  if(i>=2)samples.push(ms);
 }
 const sorted=[...samples].sort((a,b)=>a-b);console.log(label,width,height,(sorted[9]+sorted[10])/2);
 results.push({sourceWidth:source.width,sourceHeight:source.height,width,height,pixelsMatchBaseline:true,samplesMs:samples});
}
fs.writeFileSync(new URL(`./resize-${label}.json`,import.meta.url),JSON.stringify(results,null,2));

